// Accepts incoming connections and launches the sessions
class listener : public std::enable_shared_from_this<listener> {
    webcpp::asio::io_context& ioc_;
    stream_protocol::acceptor acceptor_;

public:
    // Value parameters retain the upstream callback and coroutine ownership contract.
    // NOLINTNEXTLINE(performance-unnecessary-value-param)
    listener(webcpp::asio::io_context& ioc, stream_protocol::endpoint endpoint)
        // The same completion handoff supports native owning and host borrowing overloads.
        // NOLINTNEXTLINE(performance-move-const-arg)
        : ioc_(ioc), acceptor_(ioc, std::move(endpoint)) {}

    // Start accepting incoming connections
    void run() { do_accept(); }

private:
    void do_accept() {
        // The new connection gets its own strand
        acceptor_.async_accept(net::make_strand(ioc_),
                               beast::bind_front_handler(&listener::on_accept, shared_from_this()));
    }

    void on_accept(beast::error_code ec, stream_protocol::socket socket) {
        if (ec) {
            fail(ec, "accept");
            return;
        }
        // Create the session and run it
        std::make_shared<session>(std::move(socket))->run();

        // Accept another connection
        do_accept();
    }
};

