// The process entry point retains its standard char** argv signature.
// NOLINTNEXTLINE(misc-const-correctness)
int main(int argc, char** argv) {
    {
        // Check command line arguments.
        if (argc != 3) {
            std::cerr << "Usage: websocket-server-async-local <path> <threads>\n"
                      << "Example:\n"
                      << "    websocket-server-async-local /tmp/ws.sock 1\n";
            return EXIT_FAILURE;
        }
        const auto* const path = argv[1];
        [[maybe_unused]] auto const threads = std::max<int>(1, webcpp_fixture::integer(argv[2]));

        // The io_context is required for all I/O
        webcpp::asio::io_context ioc{threads};

        // Remove previous binding
        static_cast<void>(std::remove(path));

        // Create and launch a listening port
        std::make_shared<listener>(ioc, stream_protocol::endpoint{path})->run();

        // Run the I/O service on the requested number of threads
        ioc.run();  // lint-run: drives the application's network operations

        return EXIT_SUCCESS;
    }
}

